// Real-DOM integration checks for sound stacks. Run against a fresh editor:
// node .impeccable/review/browser-check.cjs script prototype/tests/mood-stack.browser.js
async function runMoodStackChecks() {
  const results = [];
  const $ = selector => document.querySelector(selector);
  const all = selector => Array.from(document.querySelectorAll(selector));
  const check = (name, pass, detail) => results.push({name, pass: !!pass, detail: detail === undefined ? null : detail});
  const finish = () => ({ok: results.every(r => r.pass), total: results.length, passed: results.filter(r => r.pass).length, results});
  const click = selector => { const el = $(selector); if (el) el.click(); return el; };
  const input = (selector, value, type = 'input') => { const el = $(selector); if (!el) return false; el.value = value; el.dispatchEvent(new Event(type, {bubbles: true})); return true; };
  const snapshot = () => JSON.parse(localStorage.getItem('soundscape.mood-prep.v1'));
  const layer = () => snapshot().scenes.find(s => s.id === 'tavern').moods.find(m => m.id === 'evening').layers.find(l => l.id === 'evening-hearth');
  const ids = () => [layer().soundId, ...(layer().additionalSoundIds || [])];
  const rowIds = () => all('#soundSettings .stack-source').map(el => el.dataset.soundId);
  const target = '[data-layer-id="evening-hearth"]';

  click('#soundGrid .sound-card' + target + ' .sound-title');
  const add = $('#soundSettings [data-action="stack-add"]');
  check('a selected tile offers adding another sound inside that tile', !!add);
  if (!add) return finish();
  add.click();
  check('stack building opens the library with an explicit destination', document.body.classList.contains('library-open') && !$('#replacementBar').hidden && /adding to.*hearth/i.test($('#replacementName').textContent));
  input('#librarySearch', '');
  input('#libraryCategory', 'all', 'change');
  const hearth = $('#libraryResults [data-sound-id="hearth"] .library-add');
  check('a sound already in the tile cannot be added twice', !!hearth && hearth.disabled);
  click('#libraryResults [data-sound-id="wind"] .library-add');
  check('adding a source keeps one tile and its shared volume', all('#soundGrid .sound-card').length === 5 && layer().volume === 48 && ids().join(',') === 'hearth,wind', ids());
  check('the tile quietly shows its sound count', /2 sounds/.test($('#soundGrid .sound-card' + target + ' .sound-meta').textContent));
  check('the inspector lists both sources in order', rowIds().join(',') === 'hearth,wind', rowIds());
  click('#libraryResults [data-sound-id="drone"] .library-add');
  check('the same destination accepts more than two sounds', ids().join(',') === 'hearth,wind,drone' && all('#soundGrid .sound-card').length === 5, ids());
  check('stack membership participates in mood-level library deduplication', $('#libraryResults [data-sound-id="wind"] .library-add').disabled);
  click('#cancelReplace');
  check('Done finishes stack building without leaving a hidden add destination', !document.body.classList.contains('library-open') && $('#replacementBar').hidden);
  check('stack edits are saved as a working draft', /unsaved/i.test($('#saveState').textContent));

  const originalArt = $('#soundGrid .sound-card' + target + ' .sound-art').src;
  click('#soundSettings [data-action="stack-up"][data-sound-id="drone"]');
  click('#soundSettings [data-action="stack-up"][data-sound-id="drone"]');
  check('moving a sound changes the round-robin order', ids().join(',') === 'drone,hearth,wind' && rowIds().join(',') === 'drone,hearth,wind', ids());
  check('reordering preserves tile name, cover and shared volume', $('#soundGrid .sound-card' + target + ' .sound-title').textContent === 'Crackling hearth' && $('#soundGrid .sound-card' + target + ' .sound-art').src === originalArt && layer().volume === 48);
  click('#soundSettings [data-action="stack-remove"][data-sound-id="drone"]');
  check('removing the first sound promotes the next without removing the tile', ids().join(',') === 'hearth,wind' && all('#soundGrid .sound-card').length === 5, ids());
  click('#soundSettings [data-action="stack-remove"][data-sound-id="wind"]');
  check('returning to one source collapses rotation controls and protects the last source', ids().join(',') === 'hearth' && !$('#soundSettings [data-field="rotation"]') && !$('#soundSettings [data-action="stack-remove"]'));
  click('#soundSettings [data-action="stack-add"]');
  click('#libraryResults [data-sound-id="wind"] .library-add');
  click('#libraryResults [data-sound-id="drone"] .library-add');
  click('#cancelReplace');

  input('#soundSettings [data-field="rotation"]', 'random', 'change');
  check('Random changes the persisted rotation and quiet tile indicator', layer().rotation === 'random' && /Random/.test($('#soundGrid .sound-card' + target + ' .sound-meta').textContent), layer().rotation);
  const crossfadeSlider = $('#soundSettings [data-field="crossfade"]');
  input('#soundSettings [data-field="crossfade"]', '7.5');
  check('crossfade has its own live value without rebuilding the active slider', layer().crossfade === 7.5 && /7\.5s/.test($('#soundSettings [data-value-for="evening-hearth:crossfade"]').textContent) && crossfadeSlider === $('#soundSettings [data-field="crossfade"]'));
  check('between-source crossfade does not overwrite mood-entry or exit fades', layer().fadeIn === 2 && layer().fadeOut === 4);
  click('#moodStrip [data-mood-id="rain-mood"]');
  click('#moodStrip [data-mood-id="evening"]');
  click('#soundGrid .sound-card' + target + ' .sound-title');
  check('source order and rotation settings survive a mood round-trip', ids().join(',') === 'hearth,wind,drone' && $('#soundSettings [data-field="rotation"]').value === 'random' && $('#soundSettings [data-field="crossfade"]').value === '7.5');

  input('#soundSettings [data-field="rotation"]', 'round-robin', 'change');
  const next = $('#soundSettings [data-action="stack-next"]');
  check('a stack exposes a Next sound preview control, disabled until listening', !!next && next.disabled);
  if (!next) return finish();
  const current = () => $('#soundSettings .stack-source[aria-current="true"]')?.dataset.soundId;
  const previewDraft = JSON.stringify(layer());
  click('#soundGrid .sound-card' + target + ' .tile-listen');
  check('listening marks the currently playing source', current() === 'hearth' && !$('#soundSettings [data-action="stack-next"]').disabled, current());
  click('#soundSettings [data-action="stack-next"]');
  check('file-end preview advances in visible round-robin order', current() === 'wind', current());
  click('#soundSettings [data-action="stack-next"]');
  click('#soundSettings [data-action="stack-next"]');
  check('Repeat stack wraps back to the first sound', current() === 'hearth', current());
  click('#soundGrid .sound-card' + target + ' .tile-listen');
  check('stopping clears playback indicators without modifying the mix', !current() && JSON.stringify(layer()) === previewDraft);
  const repeat = $('#soundSettings [data-field="loop"]');
  repeat.checked = false; repeat.dispatchEvent(new Event('change', {bubbles: true}));
  click('#soundGrid .sound-card' + target + ' .tile-listen');
  click('#soundSettings [data-action="stack-next"]');
  click('#soundSettings [data-action="stack-next"]');
  click('#soundSettings [data-action="stack-next"]');
  check('a non-repeating stack stops after the final sound', !current() && $('#soundSettings [data-action="stack-next"]').disabled && $('#soundGrid .sound-card' + target + ' .tile-listen').getAttribute('aria-pressed') === 'false');
  repeat.checked = true; repeat.dispatchEvent(new Event('change', {bubbles: true}));
  input('#soundSettings [data-field="rotation"]', 'random', 'change');
  click('#soundGrid .sound-card' + target + ' .tile-listen');
  const played = [current()];
  click('#soundSettings [data-action="stack-next"]'); played.push(current());
  click('#soundSettings [data-action="stack-next"]'); played.push(current());
  check('Random visits all sources before repeating', new Set(played).size === 3 && played.every(Boolean), played);
  click('#soundSettings [data-action="stack-next"]');
  check('Random does not repeat the last sound at a cycle boundary', !!current() && current() !== played[2]);
  click('#soundGrid .sound-card' + target + ' .tile-listen');
  click('#previewMood');
  check('whole-mood preview also exposes the selected stack source', !!current() && !$('#soundSettings [data-action="stack-next"]').disabled);
  click('#previewMood');
  check('stopping the mood clears stack playback too', !current());

  click('#soundSettings [data-action="stack-add"]');
  const files = new DataTransfer();
  files.items.add(new File(['prototype fixture'], 'Distant strings.mp3', {type: 'audio/mpeg'}));
  $('#fileInput').files = files.files;
  $('#fileInput').dispatchEvent(new Event('change', {bubbles: true}));
  const importedFile = snapshot().library.find(s => s.name === 'Distant strings');
  check('a file import goes inside the explicit stack destination, not into a new tile', !!importedFile && ids().includes(importedFile.id) && all('#soundGrid .sound-card').length === 5 && snapshot().selectedLayerId === 'evening-hearth');
  click('#soundGrid .sound-card' + target + ' .sound-title');
  click('#soundSettings [data-action="stack-add"]');
  click('#pasteLink');
  input('#importUrl', 'https://example.com/hearth-variation.mp3');
  input('#importName', 'Hearth variation');
  $('#importForm').dispatchEvent(new Event('submit', {bubbles: true, cancelable: true}));
  click('#moodStrip [data-mood-id="rain-mood"]');
  const selectedDuringImport = snapshot().selectedLayerId;
  const deadline = Date.now() + 3000;
  while ($('#importSubmit').disabled && Date.now() < deadline) await new Promise(resolve => setTimeout(resolve, 40));
  const importedUrl = snapshot().library.find(s => s.name === 'Hearth variation');
  check('a pending URL import remembers its stack even after a mood switch', !!importedUrl && ids().includes(importedUrl.id), ids());
  check('a completed background import does not steal the current mood or selection', snapshot().activeMoodId === 'rain-mood' && snapshot().selectedLayerId === selectedDuringImport);
  click('#moodStrip [data-mood-id="evening"]');
  click('#soundGrid .sound-card' + target + ' .sound-title');
  check('returning to the stack shows both imported sources and original settings', all('#soundGrid .sound-card').length === 5 && rowIds().length === 5 && $('#soundSettings [data-field="crossfade"]').value === '7.5');
  click('#closeLibrary');

  const completeStack = JSON.stringify(layer());
  click('#soundSettings [data-action="stack-add"]');
  click('#soundSettings [data-action="remove-layer"]');
  check('removing the destination tile clears stack-building mode immediately', $('#replacementBar').hidden && all('#libraryResults .library-add:not(:disabled)').every(b => b.textContent === 'Add'));
  click('#toastAction');
  click('#soundGrid .sound-card' + target + ' .sound-title');
  check('Undo restores the entire tile, ordered sources and settings', JSON.stringify(layer()) === completeStack && all('#soundGrid .sound-card').length === 5);
  click('#soundSettings [data-action="stack-add"]');
  click('#soundGrid .add-sound');
  click('#libraryResults [data-sound-id="waves"] .library-add');
  const waveLayerId = snapshot().selectedLayerId;
  check('the grid Add sound slot explicitly leaves stack mode and creates a separate tile', all('#soundGrid .sound-card').length === 6 && ids().length === 5 && waveLayerId !== 'evening-hearth');
  click('#soundSettings [data-action="stack-add"]');
  click('#pasteLink');
  input('#importUrl', 'https://example.com/wave-variation.mp3');
  input('#importName', 'Wave variation');
  $('#importForm').dispatchEvent(new Event('submit', {bubbles: true, cancelable: true}));
  click('#soundSettings [data-action="remove-layer"]');
  const removedDeadline = Date.now() + 3000;
  while ($('#importSubmit').disabled && Date.now() < removedDeadline) await new Promise(resolve => setTimeout(resolve, 40));
  const orphanImport = snapshot().library.find(s => s.name === 'Wave variation');
  check('a removed pending-import destination leaves the new sound safely in the library, not in a surprise tile', !!orphanImport && all('#soundGrid .sound-card').length === 5 && !snapshot().scenes[0].moods.find(m => m.id === 'evening').layers.some(l => l.soundId === orphanImport.id));
  click('#closeLibrary');
  click('#soundGrid .sound-card' + target + ' .sound-title');
  click('#saveMood');
  check('Save records the full stack baseline and marks the mood clean', !/unsaved/i.test($('#saveState').textContent) && snapshot().baselines.evening.layers.find(l => l.id === 'evening-hearth').additionalSoundIds.length === 4);
  click('#duplicateMood');
  const copyMood = snapshot().scenes[0].moods.find(m => m.id === snapshot().activeMoodId);
  const copyLayer = copyMood.layers.find(l => l.name === 'Crackling hearth');
  click('#soundGrid .sound-card[data-layer-id="' + copyLayer.id + '"] .sound-title');
  click('#soundSettings [data-action="stack-remove"][data-sound-id="wind"]');
  check('editing a duplicate stack does not change the original mood', ids().length === 5 && ids().includes('wind') && rowIds().length === 4);
  click('#moodStrip [data-mood-id="evening"]');
  click('#soundGrid .sound-card' + target + ' .sound-title');

  return finish();
}
